import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二十三章 生起哪三种念想会烦恼痛苦？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/23第二十三章 生起哪三种念想会烦恼痛苦.md","filePath":"meditation/巴利文大藏经/23第二十三章 生起哪三种念想会烦恼痛苦.md"}'),o={name:"meditation/巴利文大藏经/23第二十三章 生起哪三种念想会烦恼痛苦.md"};function r(n,t,i,s,d,c){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="第二十三章-生起哪三种念想会烦恼痛苦" tabindex="-1">第二十三章 生起哪三种念想会烦恼痛苦？ <a class="header-anchor" href="#第二十三章-生起哪三种念想会烦恼痛苦" aria-label="Permalink to &quot;第二十三章 生起哪三种念想会烦恼痛苦？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部3相应23经/世间经(憍萨罗相应/有偈篇/祇夜)</p><p>有个时候，骄萨罗国的波斯匿王来到佛陀的住所，他顶礼佛陀后在一旁坐下，波斯匿王对佛陀说：“世尊，当内心生起什么念想的时候，就会让自己烦恼痛苦、无法安宁？”</p><p>佛陀说：“大王，当内心生起贪欲念想的时候，就会让自己烦恼痛苦、无法安宁；当内心生起愤怒念想的时候，就会让自己烦恼痛苦、无法安宁；当内心不明因果、没有智慧生起愚痴念想的时候，就会让自己烦恼痛苦、无法安宁。</p><p>大王，当内心生起这三种念想的时候，就会让自己烦恼痛苦、无法安宁。</p><p>内心生起贪欲、愤怒、愚痴念想的人，他们伤害别人的同时也会伤害到他们自己。就如同长满果实的树木，被很多人争相折枝采摘果实。树枝被众人折断，果树受到伤害的同时，这些人也会为果实互相争斗而受到伤害。”</p><p>这时，佛陀说偈言：</p><p>「 贪嗔以及痴，此恶心生人。</p><p>害人如害己，如争树果实。</p><p>折枝又互斗，树损人亦伤。」</p>',11)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
